package de.schaepi.puls180;
import android.Manifest;import android.content.pm.PackageManager;import android.os.Bundle;import android.hardware.Camera;import android.view.*;import android.widget.*;import com.google.zxing.*;import com.google.zxing.common.HybridBinarizer;import com.google.zxing.qrcode.QRCodeReader;
public class QrScanActivity extends FontActivity implements SurfaceHolder.Callback {
 private Camera camera;private SurfaceView preview;private TextView status;private boolean active=false,found=false;private volatile boolean decoding=false;private long lastFrame=0;private final java.util.concurrent.ExecutorService worker=java.util.concurrent.Executors.newSingleThreadExecutor();
 @Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(24,56,24,40);status=new TextView(this);status.setTextSize(19);status.setText("QR-Code am PC unter Handy koppeln anzeigen und mit der Kamera erfassen.");box.addView(status);preview=new SurfaceView(this);box.addView(preview,new LinearLayout.LayoutParams(-1,0,1));Button cancel=new Button(this);cancel.setText("Abbrechen");cancel.setOnClickListener(v->finish());box.addView(cancel);setContentView(box);preview.getHolder().addCallback(this);}
 @Override protected void onResume(){super.onResume();if(licenseBlocked())return;active=true;if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.CAMERA},421);else open();}
 @Override protected void onPause(){active=false;close();super.onPause();}
 @Override protected void onDestroy(){worker.shutdownNow();super.onDestroy();}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==421){if(g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)open();else status.setText("Zum Scannen bitte den Kamerazugriff erlauben. Alternativ kannst du den Kopplungscode im Menü einfügen.");}}
 public void surfaceCreated(SurfaceHolder holder){open();}public void surfaceChanged(SurfaceHolder h,int f,int w,int t){}public void surfaceDestroyed(SurfaceHolder h){close();}
 private void close(){if(camera!=null){try{camera.setPreviewCallback(null);camera.stopPreview();}catch(Exception ignored){}camera.release();camera=null;}}
 private void open(){if(!active||found||camera!=null||!preview.getHolder().getSurface().isValid()||checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)return;try{
 int id=-1;Camera.CameraInfo info=new Camera.CameraInfo();for(int i=0;i<Camera.getNumberOfCameras();i++){Camera.getCameraInfo(i,info);if(info.facing==Camera.CameraInfo.CAMERA_FACING_BACK){id=i;break;}}if(id<0)throw new Exception();camera=Camera.open(id);Camera.Parameters params=camera.getParameters();java.util.List<Camera.Size> sizes=params.getSupportedPreviewSizes();Camera.Size best=null;for(Camera.Size size:sizes)if(size.width<=1280&&(best==null||size.width>best.width))best=size;if(best!=null)params.setPreviewSize(best.width,best.height);params.setPreviewFormat(android.graphics.ImageFormat.NV21);java.util.List<String> focus=params.getSupportedFocusModes();if(focus!=null&&focus.contains(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE))params.setFocusMode(Camera.Parameters.FOCUS_MODE_CONTINUOUS_PICTURE);camera.setParameters(params);
 int rotation=getWindowManager().getDefaultDisplay().getRotation();int degrees=rotation==Surface.ROTATION_90?90:rotation==Surface.ROTATION_180?180:rotation==Surface.ROTATION_270?270:0;camera.setDisplayOrientation((info.orientation-degrees+360)%360);camera.setPreviewDisplay(preview.getHolder());camera.setPreviewCallback((data,cam)->{long now=android.os.SystemClock.elapsedRealtime();if(!active||found||decoding||now-lastFrame<250)return;lastFrame=now;decoding=true;Camera.Size size=cam.getParameters().getPreviewSize();byte[] frame=data.clone();worker.execute(()->{String code=null;try{PlanarYUVLuminanceSource src=new PlanarYUVLuminanceSource(frame,size.width,size.height,0,0,size.width,size.height,false);java.util.Map<DecodeHintType,Object> hints=new java.util.EnumMap<>(DecodeHintType.class);hints.put(DecodeHintType.TRY_HARDER,Boolean.TRUE);String result=new QRCodeReader().decode(new BinaryBitmap(new HybridBinarizer(src)),hints).getText();code=PcSync.validate(result);}catch(Exception ignored){}final String value=code;runOnUiThread(()->{decoding=false;if(value!=null&&active&&!found){found=true;close();boolean ok=getSharedPreferences("pcSync",0).edit().putString("code",value).putString("status","QR-Code übernommen. Abgleich startet in der Hauptliste.").commit();Toast.makeText(this,ok?"PC gekoppelt – Abgleich startet":"Kopplung konnte nicht gespeichert werden",Toast.LENGTH_LONG).show();finish();}});});});camera.startPreview();
 }catch(Exception e){close();status.setText("Kamera konnte nicht geöffnet werden. Bitte Kamerafreigabe prüfen und erneut öffnen.");}}
}


